 "content": "from collections import deque


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find the repeated three-row color key: identical nonzero horizontal runs.
    key = None
    for r in range(h - 2):
        for c in range(w):
            if g[r][c] == 0:
                continue
            end = c
            while end < w and g[r][end] != 0:
                end += 1
            seq = g[r][c:end]
            if (all(g[rr][c:end] == seq for rr in (r + 1, r + 2))
                    and (c == 0 or all(g[rr][c - 1] == 0 for rr in range(r, r + 3)))
                    and (end == w or all(g[rr][end] == 0 for rr in range(r, r + 3)))):
                key = (r, c, end, seq)
                break
        if key:
            break
    if key is None:
        return g

    kr, kc, ke, colors = key

    # The central color-1 motif is the shape to replicate.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 1 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] == 1 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            if not (kr <= r < kr + 3 and kc <= c < ke):
                components.append(comp)
    if not components:
        return g
    motif = max(components, key=len)
    top = min(r for r, _ in motif)
    left = min(c for _, c in motif)
    bottom = max(r for r, _ in motif)
    height = bottom - top + 1
    shape = {(r - top, c - left) for r, c in motif}

    # Erase the key, then stack recolored copies around the original central motif.
    for rr in range(kr, kr + 3):
        for cc in range(kc, ke):
            g[rr][cc] = 0
    first_top = top - (len(colors) // 2) * height
    for i, color in enumerate(colors):
        y0 = first_top + i * height
        for dy, dx in shape:
            y, x = y0 + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                g[y][x] = color
    return g
